from pathlib import Path
import os,pandas as pd
import mysql.connector
ROOT=Path(__file__).resolve().parents[1]; DATA=ROOT/'data/processed/cleaned_data.csv'; df=pd.read_csv(DATA)
password=os.getenv('MYSQL_PASSWORD') or input('Enter MySQL root password: '); conn=mysql.connector.connect(host='localhost',port=3306,user='root',password=password,database='job_acceptance_db'); cur=conn.cursor(); cur.execute("CREATE TABLE IF NOT EXISTS job_acceptance (candidate_id INT PRIMARY KEY, age INT, education VARCHAR(100), experience INT, current_salary DECIMAL(12,2), offered_salary DECIMAL(12,2), job_role VARCHAR(100), location VARCHAR(100), work_mode VARCHAR(50), relocation VARCHAR(20), career_growth VARCHAR(50), acceptance VARCHAR(20))")
cols=['candidate_id','age','education','experience','current_salary','offered_salary','job_role','location','work_mode','relocation','career_growth','acceptance']; q=f"INSERT INTO job_acceptance ({','.join(cols)}) VALUES ({','.join(['%s']*len(cols))}) ON DUPLICATE KEY UPDATE age=VALUES(age),education=VALUES(education),experience=VALUES(experience),current_salary=VALUES(current_salary),offered_salary=VALUES(offered_salary),job_role=VALUES(job_role),location=VALUES(location),work_mode=VALUES(work_mode),relocation=VALUES(relocation),career_growth=VALUES(career_growth),acceptance=VALUES(acceptance)"; cur.executemany(q,[tuple(r[c] for c in cols) for _,r in df.iterrows()]); conn.commit(); cur.execute('SELECT COUNT(*) FROM job_acceptance'); print('Rows in MySQL:',cur.fetchone()[0]); cur.close(); conn.close()
